export const symbols = [
  "circle",
  "square",
  "diamond",
  "triangle",
  "hexagon",
  "plus",
  "cross",
  "star",
];
export function exampleArrays() {
  // Authored inputs: one CPU-to-GPU upload when an example mounts. Rendering
  // and picking do not read plot arrays back to the host.
  const points = Array.from({ length: 240 }, (_, i) => {
    const angle = i * 2.399963229728653;
    const r = Math.sqrt((i + 0.5) / 240);
    return [2.7 * r * Math.cos(angle), 1.7 * r * Math.sin(angle)];
  });
  const curve = Array.from({ length: 129 }, (_, i) => {
    const x = -3 + (i * 6) / 128;
    return [x, Math.sin(x * 2) * 0.9];
  });
  const starts = [],
    ends = [];
  for (let j = 0; j < 7; j++)
    for (let i = 0; i < 11; i++) {
      const x = -2.7 + i * 0.54,
        y = -1.5 + j * 0.5;
      starts.push([x, y]);
      ends.push([x - y * 0.13, y + x * 0.08]);
    }
  const density = Array.from({ length: 64 }, (_, j) =>
    Array.from({ length: 128 }, (_, i) => {
      const x = (i / 127 - 0.5) * 6,
        y = (j / 63 - 0.5) * 4;
      return (
        Math.exp(-((x + 0.9) ** 2 + (y - 0.35) ** 2) / 1.2) * 0.8 +
        Math.exp(-((x - 1.2) ** 2 + (y + 0.5) ** 2) / 0.65) * 0.6
      );
    }),
  );
  const globe = Array.from({ length: 64 }, (_, j) =>
    Array.from(
      { length: 128 },
      (_, i) =>
        0.5 +
        0.3 *
          Math.cos((i / 127) * Math.PI * 2) *
          Math.cos((j / 63 - 0.5) * Math.PI) +
        0.15 * Math.sin((j / 63) * Math.PI * 4),
    ),
  );
  const rgb = Array.from({ length: 32 }, (_, j) =>
    Array.from({ length: 48 }, (_, i) => [
      i / 47,
      j / 31,
      ((Math.floor(i / 4) + Math.floor(j / 4)) % 2) * 0.65 + 0.2,
    ]),
  );
  return {
    points,
    curve,
    starts,
    ends,
    density,
    globe,
    rgb,
    segmentStarts: [[-2.5, -1.65]],
    segmentEnds: [[2.5, -1.65]],
    observations: [
      [0, 0],
      [45, 20],
      [-50, -25],
      [179, 15],
    ],
    route: [
      [-70, 0],
      [0, 40],
      [70, 0],
    ],
  };
}

